// Template accepts any type T and any callable Predicate P
template <typename T, typename P>
bool check_match(const T& val, P pred) {
    return pred(val);
}

// Custom Predicate 1: Lambda
auto is_vowel = [](char c) {
    return (c == 'a' || c == 'e');
};

// Custom Predicate 2: Function Object
struct IsOverLimit {
    int limit;
    bool operator()(int v) const { return v > limit; }
};

char c = 'a';
bool r1 = check_match(c, is_vowel); // true

int num = 150;
bool r2 = check_match(num, IsOverLimit{100}); // true
